<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Sparkles,ArrowRight,Square,RefreshCw,Check} from 'lucide-vue-next'
import {api,allPages,newKey,authGeneration} from '../api'
import {accountId,backendBase,cacheGet,cacheSet} from '../platform/bridge'
import {createGenerationController} from '../api/generation-controller'
import {selectionIdentity,selectionRequest,matchesSelection} from '../api/generation-selection'
import {defaultProfileId} from '../api/profiles'
import {writingReviewMessages} from '../api/story-writing'
import type {Profile} from '../api/types'
import type {SelectionEditScope,SelectionEditResult} from '../api/selection-edits'
const props=defineProps<{scope:SelectionEditScope;disabled?:boolean;offline?:boolean}>(),emit=defineEmits<{saved:[result:SelectionEditResult];busy:[value:boolean]}>()
const scope=JSON.parse(JSON.stringify(props.scope)) as SelectionEditScope,owner=accountId(),base=backendBase(),auth=authGeneration()
let disposed=false,hydrating=true,persistence=Promise.resolve(),writeEpoch=0
const valid=()=>!disposed&&owner===accountId()&&base===backendBase()&&auth===authGeneration(),identity=selectionIdentity(scope),draftKey='selection-ai-input:'+scope.branchId+identity
const controller=createGenerationController(scope.bookId,scope.branchId,valid,identity),purpose=ref<'expand'|'rewrite'>('expand'),instruction=ref(''),profileId=ref(''),profiles=ref<Profile[]>([]),loading=ref(true),error=ref(''),saved=ref(true),applying=ref(false),intents=new Map<string,string>(),family=ref<SelectionEditResult|null>(null)
const confirmed=ref<{generationId:string;candidateVersion:number;result:SelectionEditResult}|null>(null)
const hintText=(code:string)=>writingReviewMessages([{code:code==='CONTINUITY'?'HISTORY_CONFLICT':code==='CHARACTER_VOICE'?'CHARACTER_KNOWLEDGE':code,chapterIndex:1}])[0]
const current=computed(()=>controller.preview.value||controller.state.value),candidate=computed(()=>current.value?.chapters[0]),running=computed(()=>controller.active.value||controller.busy.value||applying.value),locked=computed(()=>!!props.disabled||running.value),inputLocked=computed(()=>locked.value||!!controller.intent.value),records=ref<{id:string;createdAt:string;state:string}[]>([])
watch(running,value=>emit('busy',value))
function persist(){if(hydrating||!valid())return persistence;const token=++writeEpoch,value={bookId:scope.bookId,purpose:purpose.value,instruction:instruction.value,intents:[...intents].slice(-40),family:family.value};saved.value=false;persistence=persistence.catch(()=>{}).then(async()=>{if(!valid())return;await cacheSet(draftKey,value);if(valid()&&token===writeEpoch)saved.value=true});void persistence.catch(e=>{if(valid())error.value=(e as Error).message});return persistence}
watch([purpose,instruction],()=>void persist())
async function flush(){await persistence;if(!saved.value)throw new Error('写作要求还未保存，请重试保存输入')}
async function retry(){try{error.value='';await persist();await flush()}catch(e){if(valid())error.value=(e as Error).message}}
async function start(){if(props.offline||locked.value||loading.value||!profileId.value||!controller.ready.value)return;try{await persist();await flush();if(!valid())return;await controller.submit(selectionRequest(scope,purpose.value,instruction.value,profileId.value))}catch(e){if(valid())error.value=(e as Error).message}}
async function apply(){const value=current.value,row=candidate.value;if(props.offline||locked.value||!value||!row||!matchesSelection(value,scope)||row.completeness!=='complete'||row.durability!=='saved')return;if(confirmed.value?.generationId===value.id&&confirmed.value.candidateVersion===value.candidateVersion){emit('saved',confirmed.value.result);return}applying.value=true;emit('busy',true);error.value='';try{const body={candidateVersion:value.candidateVersion,expectedSourceHeadRevisionId:scope.headRevisionId,sourcePolicy:scope.revisionId===scope.headRevisionId?'requireUnchanged':'forkPinned',targetBranchId:family.value?.branchId||null,expectedTargetHeadRevisionId:family.value?.revisionId||null},signature=JSON.stringify([value.id,body]),key=intents.get(signature)||newKey();intents.set(signature,key);await persist();await flush();if(!valid())return;const result=await api<SelectionEditResult>('/generations/'+encodeURIComponent(value.id)+'/selection-accept',{method:'POST',key,body});if(!valid())return;family.value=result;confirmed.value={generationId:value.id,candidateVersion:value.candidateVersion,result};try{await persist();await flush()}catch{if(valid())error.value='修订已保存，设备副本暂未同步'}if(valid()){applying.value=false;emit('busy',false);emit('saved',result)}}catch(e){if(valid())error.value=(e as Error).message}finally{if(valid()){applying.value=false;emit('busy',controller.active.value||controller.busy.value)}}}
async function history(){try{const query=new URLSearchParams({bookId:scope.bookId,branchId:scope.branchId,selections:'true',sourceRevisionId:scope.revisionId,startBlockId:scope.startAnchor.blockId,endBlockId:scope.endAnchor.blockId,startOffset:String(scope.startAnchor.start),endOffset:String(scope.endAnchor.end)}),response=await api<{items:{id:string;createdAt:string;state:string}[]}>('/generations?'+query);if(valid())records.value=response.items}catch(e){if(valid())error.value=(e as Error).message}}
async function open(id:string){if(locked.value)return;await controller.open(id);if(valid()&&controller.state.value&&!matchesSelection(controller.state.value,scope)){controller.dispose();error.value='这份写法属于其他选区，请重新打开当前选区'}}
onMounted(async()=>{try{const draft=await cacheGet<{bookId:string;purpose:'expand'|'rewrite';instruction:string;intents:[string,string][];family?:SelectionEditResult}>(draftKey);if(!valid())return;if(draft){if(draft.bookId!==scope.bookId||!['expand','rewrite'].includes(draft.purpose)||typeof draft.instruction!=='string'||draft.instruction.length>2000||!Array.isArray(draft.intents))throw new Error('选区写作输入无法读取，原记录保留');purpose.value=draft.purpose;instruction.value=draft.instruction;for(const pair of draft.intents){if(!Array.isArray(pair)||typeof pair[0]!=='string'||typeof pair[1]!=='string')throw new Error('选区请求记录无效');intents.set(pair[0],pair[1])}family.value=draft.family||null}hydrating=false;await controller.initialize();if(!valid())return;if(controller.state.value&&!matchesSelection(controller.state.value,scope))throw new Error('写作记录属于其他选区');profiles.value=await allPages<Profile>('/model-profiles');if(valid())profileId.value=defaultProfileId(profiles.value)}catch(e){if(valid())error.value=(e as Error).message}finally{if(valid())loading.value=false}})
onUnmounted(()=>{disposed=true;writeEpoch++;controller.dispose();emit('busy',false)})
defineExpose({flush})
</script>
<template><section class="selection-writing" aria-label="AI 选区写作"><fieldset :disabled="inputLocked||loading"><div class="selection-writing-modes" role="group" aria-label="写法"><button type="button" :aria-pressed="purpose==='expand'" @click="purpose='expand'"><Sparkles :size="16"/>扩写</button><button type="button" :aria-pressed="purpose==='rewrite'" @click="purpose='rewrite'">替换写法</button></div><label>改写要求<span>选填</span><textarea v-model="instruction" rows="2" maxlength="2000" placeholder="让这一幕更细腻，或试试另一种表达"/></label><select v-if="profiles.length>1" v-model="profileId" aria-label="选区写作模型"><option v-for="profile in profiles" :key="profile.id" :value="profile.id">{{profile.name}} · {{profile.modelId}}</option></select></fieldset><button v-if="!controller.state.value" type="button" class="primary" :disabled="offline||locked||loading||!saved||!profileId||!controller.supported.value" @click="start"><Sparkles :size="16"/>{{controller.intent.value?'确认提交同一次请求':'生成写法'}}</button><span v-if="!loading&&!profileId" class="muted">请先准备可用模型</span><button v-if="controller.intent.value&&!controller.intent.value.generationId" type="button" :disabled="locked" @click="controller.refresh">查询这次请求</button><article v-if="current" class="selection-writing-candidate"><div class="selection-writing-status"><small role="status">{{controller.active.value?'正在写…':candidate?.completeness==='complete'?'写法已保存':'已收到的片段'}}</small><button v-if="controller.active.value" type="button" :disabled="controller.busy.value" @click="controller.cancel"><Square :size="14"/>停止</button><button v-else type="button" :disabled="controller.busy.value" @click="controller.refresh"><RefreshCw :size="14"/>刷新记录</button></div><div class="selection-writing-prose">{{candidate?.text}}</div><div class="selection-writing-buttons"><button type="button" class="primary" :disabled="offline||locked||!candidate||candidate.completeness!=='complete'||candidate.durability!=='saved'||controller.cached.value" @click="apply"><Check :size="16"/>应用并阅读</button><button type="button" :disabled="locked" @click="controller.newDraft">另写一份</button></div><details v-if="candidate?.hints.length"><summary>写作提示</summary><p v-for="hint in candidate.hints" :key="hint.code">{{hint.message||hintText(hint.code)}}</p></details><details v-if="candidate?.rawPresentation"><summary>原返回</summary><pre>{{candidate.rawPresentation.attempts.find(a=>a.kind===candidate?.rawPresentation?.selected)?.raw}}</pre></details><details @toggle="($event.target as HTMLDetailsElement).open&&controller.loadVersions()"><summary>旧候选</summary><button v-for="version in controller.versions.value" :key="version.candidateVersion" type="button" :disabled="locked" @click="controller.selectVersion(version.candidateVersion)">写法 {{version.candidateVersion}}</button></details></article><details @toggle="($event.target as HTMLDetailsElement).open&&history()"><summary>生成记录</summary><button v-for="record in records" :key="record.id" type="button" :disabled="locked" @click="open(record.id)">{{new Date(record.createdAt).toLocaleString()}} · {{record.state==='succeeded'?'已保存':'写作记录'}}</button></details><p v-if="error||controller.error.value" role="alert" class="error">{{error||controller.error.value}}</p><button v-if="!saved" type="button" :disabled="locked" @click="retry">重试保存输入</button></section></template>
<style scoped>.selection-writing{display:grid;gap:18px;padding-top:24px;border-top:1px solid var(--line)}.selection-writing fieldset{border:0;margin:0;padding:0;display:grid;gap:16px;min-width:0}.selection-writing label{display:grid;gap:8px}.selection-writing label span{color:var(--muted);font-size:13px}.selection-writing textarea{resize:vertical;min-height:100px;font:16px/1.7 var(--font-serif,serif)}.selection-writing-modes,.selection-writing-buttons{display:flex;gap:8px;flex-wrap:wrap}.selection-writing button{min-height:44px;display:inline-flex;gap:8px;align-items:center;justify-content:center}.selection-writing-modes button[aria-pressed=true]{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}.selection-writing-candidate{display:grid;gap:18px;padding:20px;border-radius:18px;background:var(--accent-soft)}.selection-writing-status{display:flex;align-items:center;justify-content:space-between;gap:12px}.selection-writing-prose{white-space:pre-wrap;overflow-wrap:anywhere;font:17px/1.85 var(--font-serif,serif)}.selection-writing pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.selection-writing summary{min-height:44px;display:flex;align-items:center;cursor:pointer}.selection-writing details>button{margin:4px}</style>
